  "quiz": [
    {
      "id": "q1",
      "q": "二十年前霜降，被苍梧以勾结血衣教之名清理门户的是谁？",
      "options": [
        {
          "key": "A",
          "text": "段铁衣"
        },
        {
          "key": "B",
          "text": "戚长空"
        },
        {
          "key": "C",
          "text": "魏青崖"
        },
        {
          "key": "D",
          "text": "上一任掌门"
        }
      ],
      "answer": "B",
      "clue": "wf_wei_4",
      "explain": "魏青崖箱底那张清理门户令上写着：大弟子戚长空勾结血衣教，着即清理门户，落款是甄寒松与执法弟子魏青崖。"
    },
    {
      "id": "q2",
      "q": "欧小满的生父是谁？",
      "options": [
        {
          "key": "A",
          "text": "甄寒松"
        },
        {
          "key": "B",
          "text": "段铁衣"
        },
        {
          "key": "C",
          "text": "戚长空"
        },
        {
          "key": "D",
          "text": "魏青崖"
        }
      ],
      "answer": "C",
      "clue": "wf_ou_4",
      "explain": "欧小满夹袄里缝着的旧信写着：你父戚长空。"
    },
    {
      "id": "q3",
      "q": "张不问贴身收着的那半块青白玉佩，另一半在谁身上？",
      "options": [
        {
          "key": "A",
          "text": "吴阿蘅"
        },
        {
          "key": "B",
          "text": "欧小满"
        },
        {
          "key": "C",
          "text": "蓉三娘"
        },
        {
          "key": "D",
          "text": "甄寒松"
        }
      ],
      "answer": "B",
      "clue": "wf_zh_5",
      "explain": "张不问药箱夹层里的半块青白玉佩，与欧小满信里裹着的半块断口相合；吴阿蘅箱底的炭笔画也把两块描在了一起。"
    },
    {
      "id": "q4",
      "q": "甄寒松叫蓉三娘熔掉的那截断剑，原本叫什么剑？",
      "options": [
        {
          "key": "A",
          "text": "青冥"
        },
        {
          "key": "B",
          "text": "寒松"
        },
        {
          "key": "C",
          "text": "长空"
        },
        {
          "key": "D",
          "text": "无锋"
        }
      ],
      "answer": "C",
      "clue": "wf_rong_1",
      "explain": "断剑剑脊上錾着两个篆字：长空。"
    },
    {
      "id": "q5",
      "q": "八年前段铁衣为什么不肯熔那截断剑？",
      "options": [
        {
          "key": "A",
          "text": "那是血衣教的信物"
        },
        {
          "key": "B",
          "text": "剑主戚长空是被甄寒松从背后刺下断魂崖的"
        },
        {
          "key": "C",
          "text": "剑柄里藏着《无锋剑诀》"
        },
        {
          "key": "D",
          "text": "那是他师父留下的遗作"
        }
      ],
      "answer": "B",
      "clue": "wf_rong_4",
      "explain": "空心剑柄里段铁衣的纸条写着：断魂崖上，甄寒松自背后刺之，剑断坠崖。甄命熔剑灭迹，铁衣不为。"
    },
    {
      "id": "q6",
      "q": "夹在《无锋剑诀》里那张致血衣教、落款戚长空的信稿，末尾盖的是谁的印？",
      "options": [
        {
          "key": "A",
          "text": "戚长空的私印"
        },
        {
          "key": "B",
          "text": "血衣教的令印"
        },
        {
          "key": "C",
          "text": "苍梧掌门的私印"
        },
        {
          "key": "D",
          "text": "执法长老的印"
        }
      ],
      "answer": "C",
      "clue": "wf_he_4",
      "explain": "信稿末尾盖着苍梧掌门私印，涂改处的小字与正殿告示、魏青崖枕下手书一样，每一捺都带一个小钩。"
    },
    {
      "id": "q7",
      "q": "吴阿蘅当年是怎么上苍梧山的？",
      "options": [
        {
          "key": "A",
          "text": "随父亲投奔山门"
        },
        {
          "key": "B",
          "text": "被甄寒松用八两银子从人牙子手里买下"
        },
        {
          "key": "C",
          "text": "被何临渊从山洪里救上山"
        },
        {
          "key": "D",
          "text": "跟着张不问上山采药"
        }
      ],
      "answer": "B",
      "clue": "wf_he_3",
      "explain": "卖身契上写着：吴氏阿蘅，年十二，身价银八两，契主甄寒松。"
    }
  ],
